"use strict";
// Reproducible offline browser compilation of the G5 phase-defense strategy.
const fs=require("fs"),path=require("path"),crypto=require("crypto"),root=path.resolve(__dirname,"..");
const read=p=>fs.readFileSync(path.join(root,p),"utf8");
const input={
  policy:"training/zhongdi-freeze/training/policy.cjs",puct:"training/zhongdi-freeze/training/puct.cjs",model:"training/zhongdi-freeze/training/model-n64.cjs",
  search1:"training/zhongdi-freeze/strong-search-v1.1.js",search2:"training/zhongdi-freeze/strong-search-v2.js",search3:"training/zhongdi-freeze/strong-search-v3.js",
  agent:"training/zhongdi-freeze/training/league/agent.cjs",phase:"training/zhongdi-freeze/training/phase-defense.cjs"
};
const modelSource="training/zhongdi-freeze/training/models/policy-value-n64.json";
const weights=JSON.parse(read(modelSource));
if(weights.hidden!==64||weights.actions!==232||weights.input!==907||weights.policyVersion!==2)throw Error("Frozen N64 model mismatch");
const hash=p=>crypto.createHash("sha256").update(read(p)).digest("hex");
const pins=Object.fromEntries([...Object.values(input),modelSource].map(p=>[p,hash(p)]));
const modules=Object.entries(input).map(([id,file])=>"factories["+JSON.stringify(id)+"]=function(require,module,exports,__dirname){\n"+read(file)+"\n};\n").join("\n");
const chunks=[
"/* Zhongdi (中迪) — exact G5 phase-defense + G4-h13 hybrid frozen sources. */",
"/* Generated by training/build-zhongdi-browser-20261015.cjs; 16/20 vs G4 on development maps. */",
"(function(global){",
'"use strict";',
"const SOURCE_SHA="+JSON.stringify(pins)+";",
"const WEIGHTS="+JSON.stringify(weights)+";",
"const POPULATION="+JSON.stringify(JSON.parse(read("training/zhongdi-freeze/training/league/population-g4-top5-v11.json")))+";",
"const factories={};",modules,
"const cache={};",
'const names={"./policy.cjs":"policy","./league/agent.cjs":"agent","../../strong-search-v1.1.js":"search1","../../strong-search-v2.js":"search2","../../strong-search-v3.js":"search3","../puct.cjs":"puct","../model-v2.cjs":"model","../model-v3.cjs":"model","../model-n24.cjs":"model","../model-n64.cjs":"model"};',
'function load(id){if(cache[id])return cache[id].exports;if(!factories[id])throw Error("Missing Zhongdi browser module "+id);const mod={exports:{}};cache[id]=mod;factories[id](req,mod,mod.exports,"training/league");return mod.exports;}',
'function req(id){if(id==="fs")return {readFileSync:()=>JSON.stringify(WEIGHTS)};if(id==="path")return {join:(...args)=>args.join("/")};if(id==="crypto")return {};if(id==="./league/population-g4-top5-v11.json")return POPULATION;if(names[id])return load(names[id]);throw Error("Unmapped Zhongdi dependency "+id);}',
'const phase=load("phase");',
'function chooseRaw(engine,state,side,map,nodes=100){return phase.move(engine,state,side,map,"phase-defense",{nodes}).action;}',
'function choose(engine,state,side,map){const action=chooseRaw(engine,state,side,map,100);if(!action)throw Error("Zhongdi has no action");if(action.wall)return{wall:action.wall,source:"zhongdi"};return{move:action.move||action,warp:!!action.warp,source:"zhongdi"};}',
'global.MumuZhongdi=Object.freeze({id:"zhongdi-g5-phase-defense",name:"中迪",choose,chooseRaw,sourceSHA:SOURCE_SHA});',
'})(typeof window!=="undefined"?window:globalThis);'
];
const browser=chunks.join("\n")+"\n";
const out=path.join(root,"zhongdi-engine.js");
fs.writeFileSync(out,browser);
console.log("ZHONGDI_BROWSER_BUILT",JSON.stringify({bytes:Buffer.byteLength(browser),sources:pins,out}));
